{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","content":"using System.Text;

namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Parses the census CLI's positional syntax: <c>census &lt;trace.jsonl&gt;</c> and
/// <c>pairs &lt;census-tsv&gt; &lt;trace.jsonl&gt;</c>.
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>
	/// Parses the positional arguments into configuration keys.
	/// </summary>
	/// <param name="args">The command line arguments.</param>
	/// <returns>The parsed keys, or an empty dictionary when <paramref name="error"/> is set.</returns>
	/// <param name="error">Set when the arguments do not form a valid command.</param>
	public static Dictionary<string, string?> Parse(string[] args, out string? error)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
		error = null;

		if (args.Length < 1)
		{
			error = "missing command: census <trace.jsonl> | pairs <census-tsv> <trace.jsonl>";
			return dict;
		}

		var command = args[0].ToLowerInvariant();
		if (command == "census")
		{
			if (args.Length != 2)
			{
				error = "usage: census <trace.jsonl>";
				return dict;
			}

			dict["AutoWrongCensus:Command"] = "census";
			dict["AutoWrongCensus:TracePath"] = args[1];
		}
		else if (command == "pairs")
		{
			if (args.Length != 3)
			{
				error = "usage: pairs <census-tsv> <trace.jsonl>";
				return dict;
			}

			dict["AutoWrongCensus:Command"] = "pairs";
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
		}
		else
		{
			error = $"unknown command '{args[0]}': census <trace.jsonl> | pairs <census-tsv> <trace.jsonl>";
		}

		return dict;
	}
}

/// <summary>Prints the CLI usage to stdout.</summary>
public static class AutoWrongCensusUsage
{
	/// <summary>Prints the usage text to stdout.</summary>
	public static void Print()
	{
		var sb = new StringBuilder();
		sb.AppendLine("auto-wrong census (F-428 P12.13)");
		sb.AppendLine();
		sb.AppendLine("Usage:");
		sb.AppendLine("  census <trace.jsonl>            classify every auto-wrong line of a debug/batch trace");
		sb.AppendLine("  pairs <census-tsv> <trace.jsonl>  window compound/other head-word pairs (P12.18 input)");
		sb.AppendLine();
		sb.AppendLine("The census prints a TSV to stdout and a relation x site summary to stderr.");
		sb.AppendLine("Exit code 1 on a missing file or a refused trace set (sealed is measurement-only).");
		Console.Write(sb.ToString());
	}
}
","i":"Creating argument parser and usage"}

