{"content":"namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// One HoldoutGate trace line (the JSONL records <c>tools/f428-base-traces.sh</c> writes). Only the
/// fields the census reads are declared; System.Text.Json ignores the rest.
/// </summary>
public sealed record TraceLine
{
	/// <summary>The raw recipe line as written.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>The holdout row id (e.g. <c>debug:agave-margarita-395470</c>).</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>The line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>The measurement set: <c>debug</c> or <c>batch</c>; any other value is refused (D-029).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Whether the line shipped to the household without review.</summary>
	public bool Auto { get; init; }

	/// <summary>Whether the accepted row is the labelled (key) row.</summary>
	public bool Correct { get; init; }

	/// <summary>The labelled (key) row descriptions; index 0 is the key row.</summary>
	public IReadOnlyList<string> ExpectedDescriptions { get; init; } = [];

	/// <summary>The labelled (key) row dataset tiers; index 0 is the key row.</summary>
	public IReadOnlyList<string> ExpectedDataTypes { get; init; } = [];

	/// <summary>The shipped row descriptions; index 0 is the accepted row.</summary>
	public IReadOnlyList<string> ActualDescriptions { get; init; } = [];

	/// <summary>The shipped row dataset tiers; index 0 is the accepted row.</summary>
	public IReadOnlyList<string> ActualDataTypes { get; init; } = [];

	/// <summary>The resolver atoms for this line; the first accepted atom carries the site fields.</summary>
	public IReadOnlyList<TraceAtom> Atoms { get; init; } = [];
}

/// <summary>One resolver atom of a trace line.</summary>
public sealed record TraceAtom
{
	/// <summary>The atom text handed to the resolver.</summary>
	public string Text { get; init; } = string.Empty;

	/// <summary><c>accepted</c>, <c>deferred</c>, or <c>rejected</c>.</summary>
	public string Outcome { get; init; } = string.Empty;

	/// <summary>The linked ingredient master's slug, when one was linked.</summary>
	public string? LinkedIngredientId { get; init; }

	/// <summary>The parsed ingredient name.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>Whether the fdcId→master reuse path was taken.</summary>
	public bool Reused { get; init; }

	/// <summary>The decision path: <c>ranker</c>, <c>override</c>, or <c>curated</c>.</summary>
	public string Path { get; init; } = string.Empty;
}
