{"content":"using System.Collections.Frozen;
using System.Text.Json;

using LetUsCook.Fdc.Lexicon;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The raw-key set of <c>src/LetUsCook.Fdc/Lexicon/Resources/exact-overrides.json</c>, read from
/// the Fdc assembly's embedded resource — the same bytes the matcher ships, so the census's
/// override-key check can never drift from the file (D-014: the table is data, not logic).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the key set from the embedded <c>exact-overrides.json</c>.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");

		_keys = entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Whether the given (already normalised) key is in <c>exact-overrides.json</c>.</summary>
	public bool Contains(string normalizedKey) => _keys.Contains(normalizedKey);

	/// <summary>
	/// Normalises a raw line the way the matcher's raw-key override lookup does: cut at the first
	/// <c>(</c>, trim, lowercase. <see cref="LetUsCook.Fdc.Matching.FdcMatcher"/>'s own
	/// <c>StripFromParenthesis</c> is private, so this one-liner mirrors it (F-428 P12.13 report).
	/// </summary>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

#pragma warning disable CA1308 // Reason: parity with the matcher's lowercasing for override lookup.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}
}
