{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (where the line was accepted) — by calling the production helpers, never a copy of them (D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.ShouldReuse"/>, <see cref="IngredientLineResolver.SingularizeToken"/>.
/// Not thread-safe: <see cref="CarriesStateToken"/> reuses one scratch array.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar line whose key is canned but the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name keeps only the first.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: same head, different state masks.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: same head and state, different dataset tier.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: same head, state and tier, different qualifiers.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a trace field a check needed was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the ranker path reused an existing master row.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Dataset tier ranks, highest first (Foundation &gt; SrLegacy &gt; Survey &gt; Branded).</summary>
	private const int FoundationRank = 4;

	private const int SrLegacyRank = 3;

	private const int SurveyRank = 2;

	private const int BrandedRank = 1;

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused by CarriesStateToken: the production helpers take a token list, and one element is all a
	// per-token check needs. The runner classifies sequentially, so no locking.
	private readonly string?[] _singleTokenScratch = [null];

	/// <summary>Creates the classifier over the production normalizer and the exact-overrides key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins (brief P12.13 §4 order);
	/// the site comes from the atom's decision path.
	/// </summary>
	/// <param name="line">An auto-wrong trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var acceptedDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var keyTier = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var acceptedTier = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var linkedIngredientId = atom?.LinkedIngredientId;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

		var relation = ClassifyRelation(
			line.RawText,
			keyDesc,
			keyTier,
			acceptedTier,
			keyState,
			acceptedState,
			headsAgree,
			keyHeadPhrase,
			parsedNameTokens,
			keyDesc,
			acceptedDesc,
			out var missingField,
			out var keyOnlyQualifiers,
			out var acceptedOnlyQualifiers);

		var site = SiteOf(atom?.Path, atom?.Reused);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key's normalized tokens up to (not including) the first token that
	/// production marks as a state/modifier word — <see cref="FdcLexicon.ModifierWords"/>,
	/// <see cref="FdcMatcher.ExtractCandidateState"/>, or <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// on the single token. "Bread, crumbs, dry, grated, plain" is <c>bread crumbs</c>;
	/// "Tomatoes, crushed, canned" is <c>tomato</c>; "Nuts, almonds, blanched" is <c>nut almond</c>.
	/// </summary>
	/// <param name="keyTokens">The key row's normalized tokens.</param>
	/// <returns>The head phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);

		var phrase = new List<string>(keyTokens.Count);
		for (var i = 0; i < keyTokens.Count; i++)
		{
			if (CarriesStateToken(keyTokens[i]))
			{
				break;
			}

			phrase.Add(keyTokens[i]);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// unioned with <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, the same composition
	/// <c>FdcMatcher</c> feeds to <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">A normalized token list.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/> — the summary's
	/// reuse-site statistic, not a relation input.
	/// </summary>
	/// <param name="parsedName">The parser name from the trace atom.</param>
	/// <param name="linkedIngredientId">The atom's linked master slug.</param>
	/// <returns><see langword="true"/> when the production rule reuses the link.</returns>
	public static bool ProductionReuseHolds(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private static string ClassifyRelation(
		string rawText,
		string keyDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		bool headsAgree,
		IReadOnlyList<string> keyHeadPhrase,
		IReadOnlyList<string> parsedNameTokens,
		string keyDescription,
		string acceptedDescription,
		out string? missingField,
		out IReadOnlyList<string>? keyOnlyQualifiers,
		out IReadOnlyList<string>? acceptedOnlyQualifiers)
	{
		keyOnlyQualifiers = null;
		acceptedOnlyQualifiers = null;
		missingField = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return NoLabel;
		}

		if (PackUnitRegex().IsMatch(rawText)
			&& (keyState & FoodState.Canned) == FoodState.Canned
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return PackUnitState;
		}

		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		if (headsAgree)
		{
			if (keyState != acceptedState)
			{
				return StateMismatch;
			}

			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				missingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return Other;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				return RowChoiceTier;
			}

			keyOnlyQualifiers = QualifierDiff(keyDescription, acceptedDescription, true);
			acceptedOnlyQualifiers = QualifierDiff(keyDescription, acceptedDescription, false);
			return SameHeadOtherQualifier;
		}

		return SiblingFood;
	}

	private static string?[] QualifierDiff(string keyDescription, string acceptedDescription, bool keySide)
	{
		var keyQualifiers = new HashSet<string>(FdcDescriptionParser.Parse(keyDescription, FdcDataset.None).Qualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);
		var acceptedQualifiers = new HashSet<string>(FdcDescriptionParser.Parse(acceptedDescription, FdcDataset.None).Qualifiers.Select(IngredientLineResolver.SingularizeToken), StringComparer.OrdinalIgnoreCase);

		var diff = (keySide ? keyQualifiers : acceptedQualifiers).Except(keySide ? acceptedQualifiers : keyQualifiers).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
		return diff.Length > 0 ? diff : null;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string SiteOf(string? path, bool? reused) => path?.ToLowerInvariant() switch
	{
		"override" => SiteOverride,
		"curated" => SiteCurated,
		"ranker" => reused == true ? SiteReuse : SiteRanker,
		_ => string.Empty,
	};

	private static string NormalizeForOverrideKey(string rawText)
	{
		// Parity with FdcMatcher's override lookup fold (FdcMatcher.cs:165): lower-case, trimmed,
		// content from the first '(' dropped. StripFromParenthesis itself is private, so the fold is
		// applied here — the lookup is the production exact-overrides key set, not a copy of it.
		var text = rawText.Trim().ToLowerInvariant();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren].TrimEnd();
		}

		return text;
	}

	private static IReadOnlyList<string> SingularPhrase(string text) =>
		IngredientLineResolver.SingularizeToken(text);

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}
}
