{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads a HoldoutGate trace (or a P12.7 blocker-census TSV plus a trace), classifies every
/// <c>auto &amp;&amp; !correct</c> line with the production helpers, and writes the TSV to
/// <see cref="System.Console.Out"/> with the relation × site summary on <see cref="System.Console.Error"/>.
/// Refuses any trace whose record <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusRunnerOptions options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	System.IO.TextWriter output,
	System.IO.TextWriter error) : IAutoWrongCensusRunner
{
	private sealed class AutoWrongCensusRunnerOptions(AutoWrongCensusOptions options)
	{
		public string Command => options.Command;
		public string TracePath => options.TracePath;
		public string CensusTsvPath => options.CensusTsvPath;
	}

	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] TsvColumns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey",
		"acceptedTier", "keyTier", "acceptedState", "keyState",
		"parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = (IAutoWrongCensusRunnerOptions)this;
		if (options.Command.Length == 0)
		{
			await error.WriteLineAsync("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>").ConfigureAwait(false);
			Options.AutoWrongCensusUsage.Print();
			return 1;
		}

		if (!System.IO.File.Exists(options.TracePath))
		{
			await error.WriteLineAsync($"trace file not found: {options.TracePath}").ConfigureAwait(false);
			return 1;
		}

		var lines = await ReadTraceAsync(options.TracePath, error, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.Ordinal) && !l.Set.Equals("batch", StringComparison.Ordinal));
		if (refused is not null)
		{
			await error.WriteLineAsync($"refused: trace record {refused.HoldoutId}#{refused.LineIndex} has set '{refused.Set}'; only debug and batch are allowed (D-029)").ConfigureAwait(false);
			return 1;
		}

		return options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines, error)
			: await RunPairsAsync(options.CensusTsvPath, lines, error, cancellationToken).ConfigureAwait(false);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines, System.IO.TextWriter error)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();

		output.WriteLine(string.Join('\t', TsvColumns));

		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSites = 0;
		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				unknownSites++;
				error.WriteLine($"skipped {line.HoldoutId}#{line.LineIndex}: {ex.Message}");
				continue;
			}

			if (result.Site.Length == 0)
			{
				unknownSites++;
				error.WriteLine($"skipped {line.HoldoutId}#{line.LineIndex}: unknown atom path '{string.Join(" ", line.Atoms.Select(a => a.Path))}'");
				continue;
			}

			results.Add(result);
			output.WriteLine(string.Join('\t',
				Sanitize(result.HoldoutId),
				result.LineIndex.ToString(),
				Sanitize(result.Set),
				Sanitize(result.Relation),
				Sanitize(result.Site),
				Sanitize(result.OverrideKey),
				Sanitize(result.AcceptedTier),
				Sanitize(result.KeyTier),
				Sanitize(result.AcceptedState),
				Sanitize(result.KeyState),
				Sanitize(result.ParsedName),
				Sanitize(result.KeyHead),
				Sanitize(result.AcceptedDesc),
				Sanitize(result.KeyDesc),
				Sanitize(result.RawText)));
		}

		WriteSummary(results, autoWrong.Count, lines.Count, error);
		return unknownSites > 0 ? 1 : 0;
	}

	private async Task<int> RunPairsAsync(string censusTsvPath, IReadOnlyList<TraceLine> lines, System.IO.TextWriter error, CancellationToken cancellationToken)
	{
		if (!System.IO.File.Exists(censusTsvPath))
		{
			await error.WriteLineAsync($"census tsv not found: {censusTsvPath}").ConfigureAwait(false);
			return 1;
		}

		var selected = await Task.Run(
			() =>
			{
				var header = System.IO.File.ReadLines(censusTsvPath).FirstOrDefault()
					?? throw new InvalidOperationException("census tsv is empty");
				var columns = header.Split('\t').ToList();
				var blockerIndex = columns.FindIndex(c => c.Equals("blocker", StringComparison.Ordinal));
				var routeIndex = columns.FindIndex(c => c.Equals("route", StringComparison.Ordinal));
				var holdoutIndex = columns.FindIndex(c => c.Equals("holdoutId", StringComparison.Ordinal));
				var lineIndexIndex = columns.FindIndex(c => c.Equals("lineIndex", StringComparison.Ordinal));
				if (blockerIndex < 0 || routeIndex < 0 || holdoutIndex < 0 || lineIndexIndex < 0)
				{
					throw new InvalidOperationException($"census tsv is missing the blocker/route/holdoutId/lineIndex columns: {string.Join(" ", columns)}");
				}

				var selected = new List<(string HoldoutId, int LineIndex)>();
				foreach (var row in System.IO.File.ReadLines(censusTsvPath).Skip(1))
				{
					var cells = row.Split('\t');
					if (cells.Length <= Math.Max(blockerIndex, Math.Max(routeIndex, Math.Max(holdoutIndex, lineIndexIndex))))
					{
						continue;
					}

					if (!cells[holdoutIndex].Equals("window", StringComparison.Ordinal))
					{
						continue;
					}

					var route = cells[routeIndex];
					if (route.Equals("compound", StringComparison.Ordinal) || route.Equals("other", StringComparison.Ordinal))
					{
						selected.Add((cells[holdoutIndex], int.Parse(cells[lineIndexIndex])));
					}
				}

				return selected;
			},
			cancellationToken).ConfigureAwait(false);

		var traceIndex = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var missing = 0;
		foreach (var (holdoutId, lineIndex) in selected)
		{
			if (!traceIndex.TryGetValue((holdoutId, lineIndex), out var line))
			{
				missing++;
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null ? string.Empty : string.Join(' ', Singularize(normalizer.NormalizeToTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			output.WriteLine(string.Join('\t', Sanitize(holdoutId), lineIndex.ToString(), Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
		}

		if (missing > 0)
		{
			await error.WriteLineAsync($"pairs: {missing} census row(s) had no matching trace line; omitted").ConfigureAwait(false);
		}

		await error.WriteLineAsync($"pairs: {selected.Count} window compound/other row(s) selected, {selected.Count - missing} emitted").ConfigureAwait(false);
		return 0;
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, System.IO.TextWriter error, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		await foreach (var raw in System.IO.File.ReadLinesAsync(path).ConfigureAwait(false))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions) ?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				await error.WriteLineAsync($"refused: {path} is not valid trace JSONL: {ex.Message}").ConfigureAwait(false);
				return null;
			}
		}

		return lines;
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results, int autoWrongCount, int traceLineCount, System.IO.TextWriter error)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus set={set} traceLines={traceLineCount} autoWrongLines={autoWrongCount} classified={results.Count}");
		error.WriteLine("relation\tsite\tcount");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (Relation: g.Key.Relation, Site: g.Key.Site, Count: g.Count()))
			.OrderBy(x => x.Relation, StringComparer.Ordinal)
			.ThenBy(x => x.Site, StringComparer.Ordinal);
		foreach (var (relation, site, count) in matrix)
		{
			error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherRate = results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0;
		error.WriteLine($"other rate: {otherCount}/{results.Count} ({otherRate:0.0}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).Select(g => $"{g.Key}={g.Count()}");
		error.WriteLine($"missing fields: {(missing.Any() ? string.Join(" ", missing) : "none")}");

		var overrides = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrides.Count > 0)
		{
			var hits = overrides.Count(r => r.OverrideKey == "yes");
			error.WriteLine($"override site: {overrides.Count} line(s), exact-overrides.json raw-key hit {hits}");
		}

		var reuses = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuses.Count > 0)
		{
			var ruleWouldRefuse = reuses.Count(r =>
				r.ParsedName.Length > 0
				&& r.HoldoutId.Length > 0
				&& !ShouldReuseLine(r));
			error.WriteLine($"reuse site: {reuses.Count} line(s), production ShouldReuse(parsedName, linkedIngredientId) false on {ruleWouldRefuse}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			var acceptedHigher = tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
			error.WriteLine($"row-choice-tier: {tierLines.Count} line(s), key tier higher {keyHigher}, accepted tier higher {acceptedHigher}");
		}

		var qualifierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier).ToList();
		if (qualifierLines.Count > 0)
		{
			error.WriteLine($"same-head-other-qualifier: {qualifierLines.Count} line(s)");
			foreach (var r in qualifierLines)
			{
				error.WriteLine($"  {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(" ", r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(" ", r.AcceptedOnlyQualifiers ?? [])}]");
			}
		}
	}

	private static bool ShouldReuseLine(ClassificationResult r)
	{
		var slug = IngredientLineParser.ComputeSlug(r.ParsedName);
		if (slug.Length == 0)
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(slug, r.HoldoutId.Length > 0 ? r.KeyHead : slug);
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> Singularize(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value)
	{
		if (value.Length == 0)
		{
			return string.Empty;
		}

		var builder = new System.Text.StringBuilder(value.Length);
		foreach (var c in value)
		{
			builder.Append(c is '\t' or '\n' or '\r' ? ' ' : c);
		}

		return builder.ToString();
	}
}
