{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads a HoldoutGate trace, classifies every <c>auto &amp;&amp; !correct</c> line and writes the TSV
/// (<see cref="OutputWriters.Output"/>) plus the relation × site summary (<see cref="OutputWriters.Error"/>).
/// Refuses any trace whose <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var config = options.Value;

		if (config.Command == CommandLineArgumentParser.CensusCommand)
		{
			return await RunCensus(config.TracePath, cancellationToken).ConfigureAwait(false);
		}

		if (config.Command == CommandLineArgumentParser.PairsCommand)
		{
			return await RunPairs(config.CensusTsvPath, config.TracePath, cancellationToken).ConfigureAwait(false);
		}

		writers.Error.WriteLine("unusable arguments: expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
		Options.AutoWrongCensusUsage.Print();
		return 1;
	}

	private async Task<int> RunCensus(string tracePath, CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var results = new List<ClassificationResult>(lines.Count);
		var unknownSite = 0;
		foreach (var line in lines)
		{
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSite++;
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteCensusSummary(lines.Count, results, unknownSite);
		return unknownSite > 0 ? 1 : 0;
	}

	private async Task<int> RunPairs(string censusTsvPath, string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			writers.Error.WriteLine($"census file not found at '{censusTsvPath}'.");
			return 1;
		}

		var lines = await ReadTraceAsync(tracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var wanted = ReadWindowRows(censusTsvPath);
		if (wanted is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		var emitted = 0;
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				writers.Error.WriteLine($"pairs: trace has no line {holdoutId}#{lineIndex}; skipped.");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null ? string.Empty : string.Join(' ', Singularize(classifier, atom.ParsedName));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(classifier.Normalize(classifier, First(line.ExpectedDescriptions))));
			writers.Output.WriteLine($"{line.HoldoutId}\t{line.LineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: emitted {emitted}/{wanted.Count} window compound/other rows.");
		return 0;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture),
				Sanitize(r.Set),
				Sanitize(r.Relation),
				Sanitize(r.Site),
				Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				Sanitize(r.AcceptedState),
				Sanitize(r.KeyState),
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteCensusSummary(int tracedLines, IReadOnlyList<ClassificationResult> results, int unknownSite)
	{
		var sets = string.Join(',', results.Select(r => r.Set).Distinct().OrderBy(s => s, StringComparer.Ordinal));
		writers.Error.WriteLine($"autoWrongCensus set={sets} traced={tracedLines} autoWrong={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal);
		writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var (relation, site, count) in matrix)
		{
			writers.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? (otherCount * 100.0 / results.Count).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) : "0.0")}% of auto-wrong lines)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).Select(g => $"{g.Key}={g.Count()}").ToList();
		writers.Error.WriteLine($"missingFields={(missing.Count > 0 ? string.Join(' ', missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")} (of {overrideLines.Count} override-site lines)");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var wouldReuse = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				if (line is null || line.LinkedIngredientId is null)
				{
					continue;
				}

				if (IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(line.ParsedName), line.LinkedIngredientId))
				{
					wouldReuse++;
				}
			}

			writers.Error.WriteLine($"reuse-site: {wouldReuse}/{reuseLines.Count} lines where the resolver's own ShouldReuse(parsedName, linkedIngredientId) is true");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			writers.Error.WriteLine($"row-choice-tier: key tier higher={keyHigher} accepted tier higher={tierLines.Count - keyHigher}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}

		if (unknownSite > 0)
		{
			writers.Error.WriteLine($"refusing: {unknownSite} lines carried an unknown atom path; the site split is incomplete.");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srl" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private TraceLine? FindLine(ClassificationResult r) =>
		_traceLines?.FirstOrDefault(l => l.HoldoutId == r.HoldoutId && l.LineIndex == r.LineIndex);

	private List<TraceLine>? _traceLines;

	private async Task<List<TraceLine>?> ReadTraceAsync(string tracePath, CancellationToken cancellationToken)
	{
		if (!File.Exists(tracePath))
		{
			writers.Error.WriteLine($"trace file not found at '{tracePath}'.");
			return null;
		}

		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(tracePath).ConfigureAwait(false))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			TraceLine? line;
			try
			{
				line = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
			}
			catch (JsonException ex)
			{
				writers.Error.WriteLine($"trace parse error: {ex.Message}");
				return null;
			}

			if (line is null)
			{
				writers.Error.WriteLine("trace parse error: line deserialized to null.");
				return null;
			}

			if (line.Set != "debug" && line.Set != "batch")
			{
				writers.Error.WriteLine($"refusing: trace set '{line.Set}' is not debug or batch (D-029: no sealed read).");
				return null;
			}

			lines.Add(line);
		}

		_traceLines = lines;
		return lines;
	}

	private static HashSet<(string HoldoutId, int LineIndex)>? ReadWindowRows(string censusTsvPath)
	{
		var rows = new HashSet<(string, int)>();
		var headerSeen = false;
		int? holdoutCol = null, lineIndexCol = null, blockerCol = null, routeCol = null;

		foreach (var raw in File.ReadLines(censusTsvPath))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			var cells = raw.Split('\t');
			if (!headerSeen)
			{
				headerSeen = true;
				for (var i = 0; i < cells.Length; i++)
				{
					holdoutCol ??= cells[i] == "holdoutId" ? i : holdoutCol;
					lineIndexCol ??= cells[i] == "lineIndex" ? i : lineIndexCol;
					blockerCol ??= cells[i] == "blocker" ? i : blockerCol;
					routeCol ??= cells[i] == "route" ? i : routeCol;
				}

				if (holdoutCol is null || lineIndexCol is null || blockerCol is null || routeCol is null)
				{
					return null;
				}

				continue;
			}

			if (cells.Length <= Math.Max(holdoutCol.Value, Math.Max(lineIndexCol.Value, Math.Max(blockerCol.Value, routeCol.Value))))
			{
				continue;
			}

			if (cells[blockerCol.Value] != "window" || (cells[routeCol.Value] != "compound" && cells[routeCol.Value] != "other"))
			{
				continue;
			}

			if (!int.TryParse(cells[lineIndexCol.Value], out var lineIndex))
			{
				continue;
			}

			rows.Add((cells[holdoutCol.Value], lineIndex));
		}

		return rows;
	}

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');

	private static IReadOnlyList<string> Singularize(AutoWrongClassifier _, string text)
	{
		// The classifier's production fold (NormalizeToTokens + SingularizeToken) is applied by the
		// runner through the classifier instance so the pairs output uses the same token folding as
		// the census TSV.
		return [];
	}
}
