{"content":"using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.AutoWrongCensus.Services;
using LetUsCook.Fdc.Lexicon;

using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.HostedServices;

/// <summary>Builds the census host graph; the tests build the same graph through this factory.</summary>
public static class AutoWrongCensusHostBuilderFactory
{
	/// <summary>Creates the host application builder for one invocation.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <param name="output">Optional TSV sink override (tests); defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">Optional summary sink override (tests); defaults to <see cref="System.Console.Error"/>.</param>
	/// <returns>The configured builder.</returns>
	public static HostApplicationBuilder Create(string[] args, System.IO.TextWriter? output = null, System.IO.TextWriter? error = null)
	{
		ArgumentNullException.ThrowIfNull(args);

		var builder = Host.CreateApplicationBuilder(args);

		builder.Configuration.AddInMemoryCollection(CommandLineArgumentParser.Parse(args));
		builder.Services.Configure<AutoWrongCensusOptions>(builder.Configuration.GetSection(AutoWrongCensusOptions.SectionName));

		var debug = Array.Exists(args, a => a.Equals("--debug", StringComparison.OrdinalIgnoreCase) || a.Equals("--verbose", StringComparison.OrdinalIgnoreCase));
		builder.Logging.ClearProviders();
		builder.Logging.AddConsole();
		builder.Logging.SetMinimumLevel(debug ? LogLevel.Debug : LogLevel.Error);
		builder.Logging.AddFilter("Microsoft", LogLevel.Warning);

		builder.Services.AddSingleton(new OutputWriters(output ?? System.Console.Out, error ?? System.Console.Error));
		builder.Services.AddSingleton<FdcNormalizer>();
		builder.Services.AddSingleton<ExactOverrideKeyIndex>();
		builder.Services.AddSingleton<AutoWrongClassifier>();
		builder.Services.AddSingleton<IAutoWrongCensusRunner, AutoWrongCensusRunner>();
		builder.Services.AddSingleton<AutoWrongCensusHostedService>();
		builder.Services.AddHostedService(sp => sp.GetRequiredService<AutoWrongCensusHostedService>());

		return builder;
	}
}
